use anyhow::{Result,Context,bail};use glam::{Mat4,Vec3};
use crate::{gpu::{Gpu,Target},scene::{Scene,PIXEL,TABLE},source::FrameSource,log::{Log,root}};
use windows::Win32::Graphics::Direct3D11::ID3D11Texture2D;
fn pixel(bytes:&[u8],w:u32,x:u32,y:u32)->[u8;3]{let i=((y*w+x)*4)as usize;[bytes[i],bytes[i+1],bytes[i+2]]}
fn diff(a:[u8;3],b:[u8;3])->u32{a.iter().zip(b).map(|(&x,y)|x.abs_diff(y)as u32).sum()}
fn screen(p:Vec3,vp:Mat4,w:u32,h:u32)->Option<(u32,u32)>{let p=vp.project_point3(p);if p.x.abs()>0.98||p.y.abs()>0.98||p.z<0.0||p.z>1.0{return None;}Some((((p.x*0.5+0.5)*w as f32)as u32,((0.5-p.y*0.5)*h as f32)as u32))}
fn ray_triangle(o:Vec3,d:Vec3,a:Vec3,b:Vec3,c:Vec3)->Option<f32>{let e=b-a;let f=c-a;let p=d.cross(f);let det=e.dot(p);if det.abs()<1e-7{return None;}let inv=1.0/det;let t=o-a;let u=t.dot(p)*inv;if !(0.0..=1.0).contains(&u){return None;}let q=t.cross(e);let v=d.dot(q)*inv;if v<0.0||u+v>1.0{return None;}let distance=f.dot(q)*inv;if distance>0.0{Some(distance)}else{None}}
fn occluded(scene:&Scene,head:Vec3,p:Vec3,names:&[&str])->bool{let delta=p-head;let length=delta.length();let d=delta/length;for mesh in &scene.assets.meshes{if !names.contains(&mesh.name.as_str()){continue;}for instance in &mesh.instances{let model=scene.world()*Mat4::from_cols_array_2d(&instance.model);for tri in mesh.vertices.chunks_exact(3){let a=model.transform_point3(Vec3::from_array(tri[0].position));let b=model.transform_point3(Vec3::from_array(tri[1].position));let c=model.transform_point3(Vec3::from_array(tri[2].position));if ray_triangle(head,d,a,b,c).is_some_and(|t|t<length-0.002){return true;}}}}false}
fn update(scene:&mut Scene,gpu:&mut Gpu,head:Vec3,q:glam::Quat)->Result<()>{for _ in 0..12{scene.update(gpu,head,q,0.1)?;}Ok(())}
pub fn rotation_depth(scene:&Scene,gpu:&mut Gpu,texture:&ID3D11Texture2D,target:&Target,vp:Mat4,head:Vec3)->Result<serde_json::Value>{
 gpu.mask(|_|true);gpu.render(target,vp,scene.world(),true);let(_,_,covered)=gpu.pixels(texture)?;gpu.mask(|n|!["wallTop","wallSide","edgeRocks"].contains(&n));gpu.render(target,vp,scene.world(),true);let(_,_,revealed)=gpu.pixels(texture)?;gpu.mask(|n|n=="units");gpu.render(target,vp,scene.world(),true);let(_,_,only)=gpu.pixels(texture)?;gpu.mask(|_|true);let bg=pixel(&only,target.width,0,0);
 for r in &scene.source.frame(scene.time as u32).entities{if !r.alive(){continue;}let Some(model)=scene.sprite_model(r.0)else{continue;};for yi in -4..=4{for xi in -4..=4{let p=(scene.world()*model).transform_point3(Vec3::new(xi as f32*0.1,yi as f32*0.1,0.0));let Some((x,y))=screen(p,vp,target.width,target.height)else{continue;};let a=pixel(&covered,target.width,x,y);let b=pixel(&revealed,target.width,x,y);let c=pixel(&only,target.width,x,y);if diff(c,bg)>25&&diff(b,c)<8&&diff(a,b)>30&&occluded(scene,head,p,&["wallTop","wallSide","edgeRocks"]){return Ok(serde_json::json!({"id":r.0,"pixel":[x,y],"covered":a,"revealed":b,"difference":diff(a,b),"rayOccluded":true}));}}}}
 bail!("회전 테이블 벽 가림 픽셀 대상 없음")
}
pub fn run(log:&Log,scene:&mut Scene,gpu:&mut Gpu,texture:&ID3D11Texture2D,target:&Target)->Result<()> {
 scene.playing=false;scene.show_hud=false;scene.table_scale=1.0;scene.table_origin=Vec3::ZERO;scene.table_yaw=0.0;scene.table_height=TABLE;scene.seek(24600.0);let hash=scene.terrain_hash();let id=scene.source.frame(24600).entities.iter().find(|r|r.alive()&&scene.source.manifest().catalog[&r.0].kind=="champion").context("기울임 대상 없음")?.0;let row=*scene.source.frame(24600).entities.iter().find(|r|r.0==id).unwrap();let foot=Vec3::new(((row.1*0.001-480.0)*PIXEL as f64)as f32,TABLE+0.002,((row.2*0.001-480.0)*PIXEL as f64)as f32);let projection=Mat4::perspective_rh(42f32.to_radians(),target.width as f32/target.height as f32,0.01,40.0);let mut pitch=Vec::new();
 for e in [10f32,30.0,45.0,60.0,80.0]{let r=e.to_radians();let head=foot+Vec3::new(0.0,r.sin(),r.cos())*3.0;let view=Mat4::look_at_rh(head,foot,Vec3::Y);let q=view.inverse().to_scale_rotation_translation().1;let mut values=Vec::new();for enabled in [false,true]{scene.pitch_enabled=enabled;scene.reset_facing();update(scene,gpu,head,q)?;gpu.render(target,projection*view,scene.world(),true);gpu.save_png(texture,&root().join(format!("_tmp/shots/native_pitch_e{}_{}.png",e as u32,if enabled{"on"}else{"off"})))?;let value=scene.sprite_measure(id,projection*view,target.height).unwrap();if value["footError"].as_f64().unwrap()>0.00001{bail!("네이티브 발 피벗 이동");}values.push(value);}let ratio=values[1]["pixelHeight"].as_f64().unwrap()/values[0]["pixelHeight"].as_f64().unwrap();if ratio<=1.0{bail!("네이티브 기울임 높이 개선 없음");}pitch.push(serde_json::json!({"elevation":e,"off":values[0],"on":values[1],"screenHeightRatio":ratio}));}
 scene.pitch_enabled=true;scene.seek(24000.0);let(head,q,view)=crate::capture::camera(0.0,25.0,3.7);update(scene,gpu,head,q)?;let vp=projection*view;gpu.mask(|_|true);gpu.render(target,vp,scene.world(),true);let(_,_,covered)=gpu.pixels(texture)?;gpu.save_png(texture,&root().join("_tmp/shots/native_depth_covered.png"))?;gpu.mask(|n|!["wallTop","wallSide","edgeRocks"].contains(&n));gpu.render(target,vp,scene.world(),true);let(_,_,revealed)=gpu.pixels(texture)?;gpu.save_png(texture,&root().join("_tmp/shots/native_depth_revealed.png"))?;gpu.mask(|n|n=="units");gpu.render(target,vp,scene.world(),true);let(_,_,unit_only)=gpu.pixels(texture)?;let background=pixel(&unit_only,target.width,0,0);let mut depth=None;
 'find:for r in &scene.source.frame(24000).entities{if !r.alive(){continue;}let Some(model)=scene.sprite_model(r.0)else{continue;};for y in [-0.2,0.0,0.2]{for x in [-0.2,0.0,0.2]{let p=scene.world().transform_point3(model.transform_point3(Vec3::new(x,y,0.0)));let Some((px,py))=screen(p,vp,target.width,target.height)else{continue;};let a=pixel(&covered,target.width,px,py);let b=pixel(&revealed,target.width,px,py);let c=pixel(&unit_only,target.width,px,py);if diff(b,c)<6&&diff(c,background)>20&&diff(a,b)>30&&occluded(scene,head,p,&["wallTop","wallSide","edgeRocks"]){depth=Some(serde_json::json!({"id":r.0,"name":scene.source.manifest().catalog[&r.0].name,"pixel":[px,py],"covered":a,"revealed":b,"unitOnly":c,"difference":diff(a,b),"depthWrite":true}));break 'find;}}}}
 let depth=depth.context("네이티브 벽 가림 픽셀 검증 대상 없음")?;gpu.mask(|_|true);
 scene.seek(2344.0);let id=100;let row=*scene.source.frame(2344).entities.iter().find(|r|r.0==id).context("부쉬 봉술가 없음")?;let foot=Vec3::new(((row.1*0.001-480.0)*PIXEL as f64)as f32,TABLE+0.002,((row.2*0.001-480.0)*PIXEL as f64)as f32);let head=foot+Vec3::new(0.0,1.8,2.5);let view=Mat4::look_at_rh(head,foot,Vec3::Y);let q=view.inverse().to_scale_rotation_translation().1;update(scene,gpu,head,q)?;let vp=projection*view;gpu.render(target,vp,scene.world(),true);let(_,_,full)=gpu.pixels(texture)?;gpu.save_png(texture,&root().join("_tmp/shots/native_bush_visibility.png"))?;gpu.mask(|n|!["units"].contains(&n));gpu.render(target,vp,scene.world(),true);let(_,_,without)=gpu.pixels(texture)?;gpu.mask(|n|n=="units");gpu.render(target,vp,scene.world(),true);let(_,_,only)=gpu.pixels(texture)?;let background=pixel(&only,target.width,0,0);let model=scene.sprite_model(id).unwrap();let mut bush=None;
 'bush:for y in [-0.35,-0.2,0.0,0.2]{for x in [-0.3,-0.15,0.0,0.15,0.3]{let p=scene.world().transform_point3(model.transform_point3(Vec3::new(x,y,0.0)));let Some((px,py))=screen(p,vp,target.width,target.height)else{continue;};let a=pixel(&full,target.width,px,py);let b=pixel(&without,target.width,px,py);let c=pixel(&only,target.width,px,py);if diff(c,background)>20&&diff(a,b)>20{bush=Some(serde_json::json!({"id":id,"name":"pole_warrior","hp":row.3,"pixel":[px,py],"withUnit":a,"withoutUnit":b,"contribution":diff(a,b),"topOpacity":if scene.assets.closed_terrain{0.42}else{0.48},"sideOpacity":if scene.assets.closed_terrain{0.28}else{0.30},"conditionalOpacity":scene.assets.closed_terrain,"depthWrite":false}));break 'bush;}}}let bush=bush.context("부쉬 안 유닛 기여 픽셀 없음")?;gpu.mask(|_|true);if scene.terrain_hash()!=hash{bail!("카메라 이동에서 지형 변환 변경");}
 let report=serde_json::json!({"검증":"통과","pitch":pitch,"depth":depth,"bush":bush,"terrainHash":hash,"terrainTransformChanged":false,"stereoUsesOneHeadCenter":true,"실기기":"미검증"});std::fs::write(root().join("_tmp/logs/native_viewer_geometry.json"),serde_json::to_vec_pretty(&report)?)?;log.line("네이티브 기울임·발고정·벽깊이·부쉬유닛·지형고정 검증 통과");Ok(())
}
